import { sql } from "drizzle-orm";
import { integer, timestamp, uuid } from "drizzle-orm/pg-core";

/** Primary key: time-ordered UUIDv7 generated by PostgreSQL 18. */
export const id = () => uuid("id").primaryKey().default(sql`uuidv7()`);

/** Every tenant-owned table carries this column. RLS policies key on it. */
export const organizationId = () => uuid("organization_id").notNull();

export const createdAt = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
export const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

/** Optimistic-locking counter; increment on every update and compare on write. */
export const version = () => integer("version").notNull().default(1);

/** Localized label stored as { fr, en, ar }. French is the required fallback. */
export type LocalizedText = { fr: string; en?: string; ar?: string };
